(()=>{const payloads={"config-time-frame": "", "config-subjects-frame": ""},htmls={};async function unpack(id){const bytes=Uint8Array.from(atob(payloads[id]),c=>c.charCodeAt(0));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));htmls[id]=await new Response(stream).text();}Promise.all(Object.keys(payloads).map(unpack)).then(()=>setInterval(()=>{for(const id of Object.keys(htmls)){const f=document.getElementById(id);if(f&&!f.dataset.loaded){f.dataset.loaded='1';f.srcdoc=htmls[id];}}},200)).catch(e=>console.error('Configurações:',e));})();